def test_build_test_index_prunes_excluded_directories(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    from common.meta.extension import authority_classifier as ac; valid_test = tmp_path / 'tests' / 'test_valid.py'; valid_test.parent.mkdir(parents=True, exist_ok=True); valid_test.write_text('def test_valid(): pass\n', encoding='utf-8'); excluded_node = tmp_path / 'node_modules' / 'test_ignored.py'; excluded_node.parent.mkdir(parents=True, exist_ok=True); excluded_node.write_text('def test_ignored(): pass\n', encoding='utf-8'); excluded_venv = tmp_path / '.venv' / 'test_venv.py'; excluded_venv.parent.mkdir(parents=True, exist_ok=True); excluded_venv.write_text('def test_venv(): pass\n', encoding='utf-8'); visited_roots: list[str] = []; real_walk = ac.os.walk
    def spied_walk(top: Path | str, *args: Any, **kwargs: Any):
        for (root, dirs, files) in real_walk(top, *args, **kwargs): visited_roots.append(Path(root).name); yield (root, dirs, files)
    monkeypatch.setattr(ac.os, 'walk', spied_walk); index = ac.build_test_index(tmp_path); assert index.get('test_valid.py') is not None; assert index.get('test_ignored.py') is None; assert index.get('test_venv.py') is None; assert not any((root == 'node_modules' for root in visited_roots)); assert not any((root == '.venv' for root in visited_roots))
